function gWait(p) { var g = MS.g; return g ? p.t - g.stopT : 999; }
function p6Now(p) { if (p6(p) && (!p.srBlk[0] || !p.srBlk[1])) return { a: '<b>P-6 is lit: do this first.</b> Press <b>SR TRIP BLOCK train ' + (!p.srBlk[0] ? 'A' : 'B') + '</b> (counts ' + Math.round(Math.max(NI.sr[0], NI.sr[1])).toLocaleString('en-GB') + ' cps; alarm at 50,000, trip at 100,000).', pct: 0.5, ring: !p.srBlk[0] ? 'srA' : 'srB' }; return null; }
function p10Now(p) { if (!p10(p)) return null; var k = [['irBlk', 0, 'IR train A'], ['irBlk', 1, 'IR train B'], ['prBlk', 0, 'PR low train A'], ['prBlk', 1, 'PR low train B']].filter(function (q) { return !(p[q[0]] || [])[q[1]]; })[0]; return k ? { a: '<b>P-10 is lit: do this first.</b> Press the <b>P-10 BLOCK ' + k[2] + '</b> button on the front of the reactor desk (power ' + D.pr.toFixed(1) + '%, trip at 25%).' } : null; }
