ASC[0].now = function (p) { var x = p.x; if (!x.cond.some(Boolean)) return { a: 'Start <b>CONDENSATE PUMP A</b> first (steam generators board).' }; return { a: 'Turn <b>MAIN FEED PUMP A</b> to START on the steam generators &amp; feedwater board.' }; };
ASC[1].now = function (p) { var t = p.x.tb; if (!t.latched) return { a: 'Press <b>LATCH</b> on the turbine board.' }; if (t.rate !== 300) return { a: 'Set <b>ACCEL RPM/MIN</b> to <b>300</b>.' }; if (t.set < 2900) return { a: 'Turn <b>SPEED TARGET</b> to <b>3000</b>.' };
  return { a: 'Hands off: rolling up, <b>' + Math.round(t.rpm) + ' / 3000 rpm</b>, about <b>' + Math.max(1, Math.ceil((3000 - t.rpm) / t.rate)) + ' min</b> at ×1. ECCENTRICITY HIGH at the start, VIBRATION HIGH around 1400 rpm (the critical speed) and EXHAUST TEMP HIGH are all normal while it rolls: ACK them.', pct: t.rpm / 3000 }; };
ASC[2].now = function (p) { if (p.sel !== 'MAN') return { a: 'Turn the <b>BANK SELECTOR</b> to <b>MAN</b>.' + nk('5'), ring: 'sel' }; if (D.pr > 9) return rodMove(p, -1, 3, 0, 'Power ' + D.pr.toFixed(1) + '%: too close to P-10.');
  if (p.sur > 0.5) return { a: 'Hands off: startup rate ' + p.sur.toFixed(2) + ' DPM. Let it settle.' }; var m = rodMove(p, 1, 3, 30, 'Power <b>' + D.pr.toFixed(1) + '%</b> → 6–8%.'); m.pct = clamp(D.pr / 6, 0, 1); return m; };
