ASC[5].now = function (p) { if (p.sel !== 'AUTO') return { a: 'Turn the <b>BANK SELECTOR</b> to <b>AUTO</b>.', ring: 'sel' }; return { a: 'Turn <b>DUMP MODE</b> to <b>TAVG</b> on the main steam board.' }; };
