SHUT[0].now = function (p) { if (p.sel !== 'MAN') return { a: 'Turn the <b>BANK SELECTOR</b> to <b>MAN</b>.' + nk('5'), ring: 'sel' }; return { a: 'Hold the lever at <b>IN</b>' + (nk('I') ? ' (' + nk('I') + ')' : '') + ' and keep holding until the white <b>P-6</b> lamp goes out: about 10 min at ×1, 30 s at ×20 (' + pcName(p.pc) + ').', pct: 1 - p.pc / PCMAX, ring: 'lever' }; };
