  var ph = MS.phase(), P = ph === 'start' || ph === 'shut' ? phaseDef(ph) : null, s = P && P.list[firstOpen(P.list, MS[P.fl])], n = s && s.now && S.cfg.guide !== false ? s.now(S.p) : null, a = n && n.ring && GUIDE.at[n.ring];
