PLAY.mgBest = function (k, v, hiGood) { var B = PLAY.sv().mini || {}, old = B[k], nb = old == null || (hiGood ? v > old : v < old); if (nb) PLAY.put(function (p) { p.mini = p.mini || {}; p.mini[k] = v; }); return nb; };
