PLAY.station = function () { PLAY.grants(true); var P = PLAY.sv(), m = PLAY.money(), val = 2e9 + PLAY.UPG.filter(function (q) { return PLAY.upg(q.id); }).reduce(function (a, q) { return a + q.c * 3; }, 0);
  menu('<div class="cpnst"><h1>🏭 My station</h1><p class="cpnsub">Every MWh you send to the grid earns money at today’s price (now ' + PLAY.gbp(PLAY.price()) + '/MWh, earnings ×' + PLAY.earnMul().toFixed(2) + '). Every lesson you finish in Critical brings a £15,000 training grant.</p>' + PLAY.site() +
    '<p><b>Station money: ' + PLAY.gbp(m) + '</b> · lessons funded: ' + (P.lessons || 0) + ' · station value ' + PLAY.gbp(val) + '</p><div class="upl">' + PLAY.UPG.map(function (q) { var own = PLAY.upg(q.id); return '<div class="up' + (own ? ' own' : '') + '"><b>' + q.ic + ' ' + esc(q.n) + '</b><span>' + esc(q.d) + '</span>' + (own ? '<span style="color:#4ade80">✓ Built</span>' : '<button class="' + (m >= q.c ? 'cpnb' : 'cpnb2') + '" data-a="buy" data-v="' + q.id + '">' + (m >= q.c ? 'Build for ' : 'Needs ') + PLAY.gbp(q.c) + '</button>') + '</div>'; }).join('') + '</div>' +
    '<div class="cpnbtns"><button class="cpnb2" data-a="back">← Back</button></div></div>',
    function (a, b) { if (a === 'back') PLAY.hub(); if (a === 'buy') { var q = PLAY.UPG.filter(function (z) { return z.id === b.dataset.v; })[0]; if (!q) return; if (PLAY.money() < q.c) { AUD.sfx('deny'); toast('Not enough money yet: you need ' + PLAY.gbp(q.c - PLAY.money()) + ' more. Run the plant, finish lessons in Critical, and win challenges.', 'warn'); return; }
      PLAY.put(function (p) { p.money -= q.c; p.upg = p.upg || {}; p.upg[q.id] = CAR.today(); }); AUD.sfx('done'); PLAY.xp(100, 'Built: ' + q.n, true); toast('🏗 ' + q.n + ' built!', 'ok'); PLAY.station(); } }); };

/* ---------- the supervisor's question: Critical's lessons, asked in the control room ---------- */
PLAY.BANK = [['What does a control rod do?', ['Absorbs neutrons to slow the chain reaction', 'Heats the coolant', 'Speeds neutrons up', 'Makes steam'], 0, 'Control rods soak up neutrons, so fewer fissions happen.'],
  ['What does “critical” mean for a reactor?', ['The chain reaction is steady: k = 1', 'It is about to explode', 'Power is rising fast', 'All rods are in'], 0, 'Critical means each fission causes exactly one more on average. It’s normal operation.'],
  ['Why is boron dissolved in the coolant?', ['It absorbs neutrons evenly across the core', 'It stops corrosion', 'It cools the fuel', 'It makes the water heavier'], 0, 'Boron is a neutron absorber spread through all the water: a slow, even way to control reactivity.'],
  ['What happens to reactivity when the coolant gets hotter (negative MTC)?', ['It falls, so power falls', 'It rises', 'Nothing', 'The rods drop'], 0, 'Hotter water is less dense and slows fewer neutrons, so reactivity falls. That makes the reactor stable.'],
  ['Roughly how much of the heat becomes electricity in a PWR?', ['About a third', 'About 90%', 'About 10%', 'All of it'], 0, 'About 33%: the rest leaves as warm water through the condenser.'],
  ['What is the job of the pressuriser?', ['Keeps the primary water under pressure so it doesn’t boil', 'Makes the steam for the turbine', 'Stores spare fuel', 'Cools the containment'], 0, 'At 155 bar the primary water stays liquid at over 300 °C.'],
  ['Which particle keeps a fission chain reaction going?', ['Neutrons', 'Electrons', 'Alpha particles', 'Photons'], 0, 'Each fission releases 2 or 3 neutrons that can split more nuclei.'],
  ['What does SCRAM / reactor trip do?', ['Drops all the control rods in at once', 'Opens the turbine valves', 'Adds more fuel', 'Turns off the lights'], 0, 'A trip lets all the rods fall into the core under gravity, shutting the reaction down in seconds.']];
PLAY.quiz = function () { var q = null; try { var pool = window.__crit && window.__crit.reviewPool ? window.__crit.reviewPool(false).filter(function (c) { return c.t === 'Q' && c.o && c.o.length >= 2 && c.o.length <= 5; }) : []; if (pool.length) { var c = pool[Math.floor(Math.random() * pool.length)]; q = [c.p, c.o, c.a, c.e || '', true, c._src || '']; } } catch (e) {}
  if (!q) { var b = PLAY.BANK[Math.floor(Math.random() * PLAY.BANK.length)]; q = [esc(b[0]), b[1].map(esc), b[2], esc(b[3]), false, '']; }
  var order = q[1].map(function (_, i) { return i; }).sort(function () { return Math.random() - 0.5; }); S.wasPaused = false; setPause(true); speak('Quick question.');
  menu('<h1>👷 The supervisor asks…</h1>' + (q[4] ? '<p class="cpnsub">From your Critical lessons' + (q[5] ? ': ' + esc(q[5]) : '') + '</p>' : '') + '<p style="font-size:17px">' + q[0] + '</p><div class="cpnbtns" style="flex-direction:column;align-items:stretch">' + order.map(function (i) { return '<button class="cpnb2" data-a="q" data-v="' + i + '" style="text-align:left">' + q[1][i] + '</button>'; }).join('') + '</div>',
    function (a, b) { if (a !== 'q') { if (a === 'x') closeMenu(); return; } var ok = +b.dataset.v === q[2]; if (ok) { AUD.sfx('ok'); PLAY.xp(15, 'Supervisor’s question'); PLAY.pay(10000, 'right answer'); } else AUD.sfx('deny');
      S.menu.querySelector('.cpncard').innerHTML = '<h1>' + (ok ? '✔ Spot on' : '✘ Not quite') + '</h1><p><b>Answer:</b> ' + q[1][q[2]] + '</p>' + (q[3] ? '<p>' + q[3] + '</p>' : '') + '<div class="cpnbtns"><button class="cpnb" data-a="x">Back to the board</button></div>'; }); };

/* ---------- story mode: your first year at Critical Point ---------- */
PLAY.CAST = { priya: ['👩‍✈️', 'Priya, shift supervisor'], dev: ['👷', 'Dev, field operator'], neso: ['📞', 'NESO control'], you: ['🙂', 'You'] };
