  month: function (c) { return Math.min(11, Math.floor(c * 12 / 52)); },
  doneIn: function (c) { var d = SAGA.sv().done || {}, n = 0; for (var k = 0; k < 3; k++) if (d[c + '.' + k]) n++; return n; },
  open: function (c) { var s = SAGA.sv(); if (c === 0 || s.all) return true; if (!s.t0) return false; return Date.now() >= s.t0 + c * SAGA.WEEK && SAGA.doneIn(c - 1) > 0; },
  when: function (c) { var s = SAGA.sv(); if (!s.t0) return ''; var t = s.t0 + c * SAGA.WEEK; return Date.now() >= t ? (SAGA.doneIn(c - 1) ? '' : 'play chapter ' + c + ' first') : 'opens ' + new Date(t).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }); },
