  burst: function (f, q, vol, dur, type) { var c = AUD.ctx, s = c.createBufferSource(); s.buffer = AUD.nbuf; var bp = c.createBiquadFilter(); bp.type = type || 'bandpass'; bp.frequency.value = f; bp.Q.value = q; var g = c.createGain(), t = c.currentTime + 0.005; g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0005, t + dur); s.connect(bp); bp.connect(g); g.connect(OUTA.out); s.start(t); s.stop(t + dur + 0.02); },
