  var E = TR.col || (TR.col = el('div', 'fxcall')); E.hidden = false; E.innerHTML = ''; if (!E.isConnected) root.appendChild(E); TR.colT = performance.now();
  var line = function (who, txt, say) { var q = el('div', '', '<b class="' + (who === 'SRO' ? 's' : '') + '">' + who + ':</b> ' + esc(txt)); E.appendChild(q); TR.colT = performance.now(); if (say) speak(txt); };
  var rods = function () { return BANKS.every(function (b) { return p.rods[b] <= 0; }); }, fl = function () { return p.n < 0.05 ? 'flux falling' : 'flux still high'; };
  var tb = function () { var x = p.x; return !x || !x.tb || !x.tb.latched; }, si = function () { return !!(p.x && p.x.si && p.x.si.on); };
