  start: function (k) { var p = S.p, x = p.x, sb = x.sbo || (x.sbo = { on: [false, false], up: [false, false], at: [0, 0] }); if (sb.on[k]) return; sb.on[k] = true; sb.at[k] = p.t + 120; AUD.sfx('switch'); S.addLog('SBO diesel ' + (k + 1) + ' start ordered'); toast('SBO diesel ' + (k + 1) + ' starting: about 2 minutes to load it'); }
